"""Inspect the drawn content in the two PDFs generated by the browser fixture."""
from pathlib import Path
import fitz

root = Path(__file__).resolve().parents[1] / "test-results"
for scope in ("pair", "chat"):
    with fitz.open(root / f"rich-{scope}.pdf") as doc:
        pages = list(doc)
        text = "\n".join(p.get_text() for p in pages)
        for phrase in ("Start", "Ready?", "Process", "Retry", "Yes", "No",
                       "☑", "☐", "⊟", "中文", "日本語", "한국어", "Français",
                       "Inner widget output", "frame contents unavailable",
                       "0, 1, 1, 2, 3, 5, 8, 13", "Display mode: Sequence"):
            assert phrase in text, phrase
        assert "preview unavailable" not in text and "flowchart LR" not in text
        assert "private frame contents" not in text
        fonts = {f[3].split("+")[-1] for p in pages for f in p.get_fonts()}
        assert {"NotoSansDevanagari-Regular", "NotoSansSC-Regular", "NotoSansKR-Regular"} <= fonts
        def box(s):
            return next(r for p in pages for r in p.search_for(s))
        assert box("Start").x0 < box("Ready?").x0 < box("Process").x0
        assert box("Process").y0 < box("Retry").y0
        assert box("Nested circle").x0 > box("Fourth item").x0
        theorem = box("Theorem.")
        assert any(d["rect"].width == 0 and d["rect"].x0 < theorem.x0 and
                   d["rect"].y0 <= theorem.y0 < d["rect"].y1 and d["width"] == 2
                   for p in pages for d in p.get_drawings())
        assert box("Slider: 8").width > 0
        tracks = [d["rect"] for p in pages for d in p.get_drawings()
                  if d.get("width") == 2 and d["rect"].height == 0]
        assert any(abs(a.width - 160) < .01 and abs(b.width - 80) < .01
                   and a.tl == b.tl for a in tracks for b in tracks)
    print(f"rich-{scope}.pdf passed diagram, checklist, quote, list, Unicode and slider checks")
